class Solution {
public:
    bool isAdditiveNumber(string num) {
        int n = num.size();
        auto add = [](const string& a, const string& b) {
            string res;
            int i = a.size() - 1, j = b.size() - 1, carry = 0;
            while (i >= 0 || j >= 0 || carry) {
                int d = carry;
                if (i >= 0) d += a[i--] - '0';
                if (j >= 0) d += b[j--] - '0';
                res.push_back(d % 10 + '0');
                carry = d / 10;
            }
            reverse(res.begin(), res.end());
            return res;
        };
        for (int i = 1; i <= n / 2; ++i) {
            if (num[0] == '0' && i > 1) break;
            for (int j = i + 1; j < n; ++j) {
                if (num[i] == '0' && j - i > 1) break;
                string a = num.substr(0, i), b = num.substr(i, j - i);
                long long pos = j;
                while (pos < n) {
                    string s = add(a, b);
                    if (num.compare(pos, s.size(), s) != 0) break;
                    pos += s.size();
                    a = b; b = s;
                }
                if (pos == n) return true;
            }
        }
        return false;
    }
};

